func matchesString(c storage.EvaluationConstraint, v string) bool {
	switch c.Operator {
	case flipt.OpEmpty:
		return len(strings.TrimSpace(v)) == 0
	case flipt.OpNotEmpty:
		return len(strings.TrimSpace(v)) != 0
	case flipt.OpIsOneOf, flipt.OpIsNotOneOf:
		var values []string
		if err := json.Unmarshal([]byte(c.Value), &values); err != nil || values == nil || jsonArrayHasNull(c.Value) {
			return c.Operator == flipt.OpIsNotOneOf
		}
		for _, value := range values {
			if value == v {
				return c.Operator == flipt.OpIsOneOf
			}
		}
		return c.Operator == flipt.OpIsNotOneOf
	}

	if v == "" {
		return false
	}

	value := c.Value

	switch c.Operator {
	case flipt.OpEQ:
		return value == v
	case flipt.OpNEQ:
		return value != v
	case flipt.OpPrefix:
		return strings.HasPrefix(strings.TrimSpace(v), value)
	case flipt.OpSuffix:
		return strings.HasSuffix(strings.TrimSpace(v), value)
	}

	return false
}

func matchesNumber(c storage.EvaluationConstraint, v string) (bool, error) {
	switch c.Operator {
	case flipt.OpNotPresent:
		return len(strings.TrimSpace(v)) == 0, nil
	case flipt.OpPresent:
		return len(strings.TrimSpace(v)) != 0, nil
	}
	if c.Operator == flipt.OpIsOneOf || c.Operator == flipt.OpIsNotOneOf {
		var values []float64
		if err := json.Unmarshal([]byte(c.Value), &values); err != nil || values == nil || jsonArrayHasNull(c.Value) {
			return false, errs.ErrInvalidf("invalid number list %q", c.Value)
		}
		if v == "" {
			return false, nil
		}
		n, err := strconv.ParseFloat(v, 64)
		if err != nil {
			return false, errs.ErrInvalidf("parsing number from %q", v)
		}
		for _, value := range values {
			if value == n {
				return c.Operator == flipt.OpIsOneOf, nil
			}
		}
		return c.Operator == flipt.OpIsNotOneOf, nil
	}

	// can't parse an empty string
	if v == "" {
		return false, nil
	}

	n, err := strconv.ParseFloat(v, 64)
	if err != nil {
		return false, errs.ErrInvalidf("parsing number from %q", v)
	}

	// TODO: we should consider parsing this at creation time since it doesn't change and it doesnt make sense to allow invalid constraint values
	value, err := strconv.ParseFloat(c.Value, 64)
	if err != nil {
		return false, errs.ErrInvalidf("parsing number from %q", c.Value)
	}

	switch c.Operator {
	case flipt.OpEQ:
		return value == n, nil
	case flipt.OpNEQ:
		return value != n, nil
	case flipt.OpLT:
		return n < value, nil
	case flipt.OpLTE:
		return n <= value, nil
	case flipt.OpGT:
		return n > value, nil
	case flipt.OpGTE:
		return n >= value, nil
	}

	return false, nil
}

